import numpy as np

def rotate2d(p, th):
    x, y = p
    c, s = np.cos(th), np.sin(th)
    return np.array([x * c - y * s, x * s + y * c])

p = np.array([1.0, 0.0])
for deg in (0, 90, 180, 270):
    r = rotate2d(p, np.radians(deg))
    print(deg, "deg ->", np.round(r, 4))

