import numpy as np

def rotz(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

def is_rotation(R, tol=1e-8):
    if R.shape != (3, 3):
        return False
    orthonormal = np.allclose(R.T @ R, np.eye(3), atol=tol)
    proper = abs(np.linalg.det(R) - 1.0) < tol
    return bool(orthonormal and proper)

R = rotz(np.radians(20))
mirror = R.copy()
mirror[:, 0] *= -1

print("rotation:", is_rotation(R), "det", round(float(np.linalg.det(R)), 6))
print("mirror:", is_rotation(mirror), "det", round(float(np.linalg.det(mirror)), 6))

