lessons.solution:
import numpy as np

def skew(k):
    kx, ky, kz = k
    return np.array([[0, -kz, ky],
                     [kz, 0, -kx],
                     [-ky, kx, 0]], dtype=float)

def rodrigues(k, th):
    k = np.asarray(k, dtype=float)
    n = np.linalg.norm(k)
    if n < 1e-12:
        raise ValueError("rotation axis must be non zero")
    k = k / n
    K = skew(k)
    return np.eye(3) + np.sin(th) * K + (1 - np.cos(th)) * (K @ K)

def rotz(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

R = rodrigues([0.0, 0.0, 1.0], np.radians(90))
print("matches rotz:", np.allclose(R, rotz(np.radians(90))))
print("skew acts as cross:", np.allclose(skew([1.0, 2, 3]) @ np.array([4.0, 5, 6]),
                                        np.cross([1.0, 2, 3], [4.0, 5, 6])))

