import numpy as np

def rotz(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

R_drifted = rotz(np.radians(25)) + 1e-3 * np.ones((3, 3))

def orthonormalise(R):
    U, _, Vt = np.linalg.svd(R)
    Rn = U @ Vt
    if np.linalg.det(Rn) < 0:
        U[:, 2] *= -1
        Rn = U @ Vt
    return Rn

def err(R):
    return float(np.linalg.norm(R.T @ R - np.eye(3)))

R_fixed = orthonormalise(R_drifted)
print("error before:", round(err(R_drifted), 8))
print("error after:", round(err(R_fixed), 12))
print("determinant after:", round(float(np.linalg.det(R_fixed)), 9))

