import numpy as np

def rotx(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])

def roty(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])

def rotz(th):
    c, s = np.cos(th), np.sin(th)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

def rpy_to_R(r, p, y):
    return rotz(y) @ roty(p) @ rotx(r)

def R_to_rpy(R, eps=1e-6):
    margin = np.hypot(R[2, 1], R[2, 2])
    if margin > eps:
        pitch = -np.arcsin(np.clip(R[2, 0], -1.0, 1.0))
        roll = np.arctan2(R[2, 1], R[2, 2])
        yaw = np.arctan2(R[1, 0], R[0, 0])
    elif R[2, 0] < 0:
        pitch, roll = np.pi / 2, 0.0
        yaw = np.arctan2(-R[0, 1], R[1, 1])
    else:
        pitch, roll = -np.pi / 2, 0.0
        yaw = np.arctan2(-R[0, 1], R[1, 1])
    return float(roll), float(pitch), float(yaw)

R = rpy_to_R(np.radians(30), np.pi / 2, np.radians(15))
r, p, y = R_to_rpy(R)
print("triple:", np.round(np.degrees([r, p, y]), 3))
print("no nan:", not any(np.isnan([r, p, y])))
print("round trip ok:", np.allclose(rpy_to_R(r, p, y), R))

locked = [(np.radians(rd), sign * np.pi / 2, np.radians(yd))
          for rd in range(-180, 180, 30)
          for yd in (-140.0, -35.0, 20.0, 95.0, 170.0)
          for sign in (1.0, -1.0)]
closed = 0
for triple in locked:
    M = rpy_to_R(*triple)
    if np.allclose(rpy_to_R(*R_to_rpy(M)), M):
        closed = closed + 1
print("degenerate poses that close the round trip:", closed, "of", len(locked))

