import numpy as np

class Frame:
    def __init__(self, a, b, T):
        self.a, self.b, self.T = a, b, np.asarray(T, float)

    def then(self, other):
        if self.b != other.a:
            raise ValueError("cannot chain T_{}_{} with T_{}_{}".format(self.a, self.b, other.a, other.b))
        return Frame(self.a, other.b, self.T @ other.T)

    def inverse(self):
        R, p = self.T[:3, :3], self.T[:3, 3]
        T = np.eye(4)
        T[:3, :3] = R.T
        T[:3, 3] = -R.T @ p
        return Frame(self.b, self.a, T)

