import numpy as np

def make_T(R, p):
    T = np.eye(4)
    T[:3, :3] = R
    T[:3, 3] = p
    return T

def inv_T(T):
    R, p = T[:3, :3], T[:3, 3]
    out = np.eye(4)
    out[:3, :3] = R.T
    out[:3, 3] = -R.T @ p
    return out

class TF:
    def __init__(self, root="world"):
        self.root = root
        self.links = {}

    def add(self, child, parent, T):
        self.links[child] = (parent, np.asarray(T, float))

    def to_root(self, frame):
        if frame == self.root:
            return np.eye(4)
        T = np.eye(4)
        seen = set()
        while frame != self.root:
            if frame not in self.links:
                raise KeyError("frame {} is not connected to {}".format(frame, self.root))
            if frame in seen:
                raise ValueError("cycle in the transform tree at {}".format(frame))
            seen.add(frame)
            parent, Tpc = self.links[frame]
            T = Tpc @ T
            frame = parent
        return T

    def lookup(self, a, b):
        return inv_T(self.to_root(a)) @ self.to_root(b)

