import numpy as np

L1, L2 = 0.20, 0.15

def jacobian_2r(q):
    s1, c1 = np.sin(q[0]), np.cos(q[0])
    s12, c12 = np.sin(q[0] + q[1]), np.cos(q[0] + q[1])
    return np.array([[-L1 * s1 - L2 * s12, -L2 * s12],
                     [L1 * c1 + L2 * c12, L2 * c12]])

def dls_inverse(J, lam):
    m = J.shape[0]
    return J.T @ np.linalg.inv(J @ J.T + (lam ** 2) * np.eye(m))

def adaptive_lambda(J, eps=0.02, lam_max=0.08):
    s_min = float(np.linalg.svd(J, compute_uv=False)[-1])
    if s_min >= eps:
        return 0.0, s_min
    return float(np.sqrt(1 - (s_min / eps) ** 2) * lam_max), s_min

