    J = jacobian_2r(np.array([0.0, np.radians(deg)]))
    lam, s_min = adaptive_lambda(J)
    plain = np.linalg.pinv(J) @ v
    damped = dls_inverse(J, lam) @ v
    print("elbow {:5.1f} deg  s_min {:.5f}  lam {:.4f}  pinv rate {:9.2f}  dls rate {:7.2f}".format(
