import numpy as np

L1, L2 = 0.20, 0.15

def fk(q):
    return np.array([L1 * np.cos(q[0]) + L2 * np.cos(q[0] + q[1]),
                     L1 * np.sin(q[0]) + L2 * np.sin(q[0] + q[1])])

def jac(q):
    s1, c1 = np.sin(q[0]), np.cos(q[0])
    s12, c12 = np.sin(q[0] + q[1]), np.cos(q[0] + q[1])
    return np.array([[-L1 * s1 - L2 * s12, -L2 * s12],
                     [L1 * c1 + L2 * c12, L2 * c12]])

def dls_inverse(J, lam):
    return J.T @ np.linalg.inv(J @ J.T + (lam ** 2) * np.eye(J.shape[0]))

def adaptive_lambda(J, eps=0.02, lam_max=0.06):
    s_min = float(np.linalg.svd(J, compute_uv=False)[-1])
    return 0.0 if s_min >= eps else float(np.sqrt(1 - (s_min / eps) ** 2) * lam_max)

def ik_dls(fk, jac, q0, target, tol=1e-9, max_iter=100, max_step=0.05):
    q = np.asarray(q0, float).copy()
    target = np.asarray(target, float)
    for it in range(1, max_iter + 1):
        e = target - fk(q)
        err = float(np.linalg.norm(e))
        if err < tol:
            return q, it, err
        if err > max_step:
            e = e * (max_step / err)
        J = jac(q)
        q = q + dls_inverse(J, adaptive_lambda(J)) @ e
    return q, max_iter, float(np.linalg.norm(target - fk(q)))

