def jac_pose(q, h=1e-7):
    J = np.zeros((3, 3))
    for i in range(3):
        d = np.zeros(3); d[i] = h
        J[:, i] = (fk_pose(q + d) - fk_pose(q - d)) / (2 * h)
    return J

def wrap_pi(a):
    return (a + np.pi) % (2 * np.pi) - np.pi

def pose_error(cur, tgt, w_rot=0.2):
    e = np.zeros(3)
    e[:2] = tgt[:2] - cur[:2]
    e[2] = w_rot * wrap_pi(tgt[2] - cur[2])
    return e

def dls_inverse(J, lam):
    return J.T @ np.linalg.inv(J @ J.T + (lam ** 2) * np.eye(J.shape[0]))

def ik_pose(q0, target, tol=1e-9, max_iter=200):
    q = np.asarray(q0, float).copy()
    for it in range(1, max_iter + 1):
        e = pose_error(fk_pose(q), target)
        if np.linalg.norm(e) < tol:
            return q, it, float(np.linalg.norm(e))
        J = jac_pose(q)
        s_min = float(np.linalg.svd(J, compute_uv=False)[-1])
        lam = 0.0 if s_min >= 0.02 else float(np.sqrt(1 - (s_min / 0.02) ** 2) * 0.05)
        q = q + dls_inverse(J, lam) @ e
    return q, max_iter, float(np.linalg.norm(pose_error(fk_pose(q), target)))

target = np.array([0.30, 0.10, np.radians(35)])
q, iters, err = ik_pose([0.2, 0.6, -0.2], target)
got = fk_pose(q)
print("joints deg:", np.round(np.degrees(q), 4), "iterations:", iters)
print("position error:", round(float(np.linalg.norm(got[:2] - target[:2])), 12))
print("tool angle error deg:", round(float(np.degrees(wrap_pi(got[2] - target[2]))), 10))

