import numpy as np

TURN = np.pi / 2
R_CORNER = 0.20
CORNER_STEPS = (3, 5, 4, 8)

LAP = []
for n in CORNER_STEPS:
    LAP += [(0.02, 0.0)] * 40
    LAP += [(R_CORNER * TURN / n, TURN / n)] * n

SPIN_LAP = []
for n in CORNER_STEPS:
    SPIN_LAP += [(0.02, 0.0)] * 40
    SPIN_LAP += [(0.0, TURN / n)] * n

def wrap_pi(a):
    return (a + np.pi) % (2 * np.pi) - np.pi

def odom_mid(pose, ds, dth):
    x, y, th = pose
    return np.array([x + ds * np.cos(th + dth / 2), y + ds * np.sin(th + dth / 2), wrap_pi(th + dth)])

def odom_exact(pose, ds, dth):
    x, y, th = pose
    if abs(dth) < 1e-9:
        return np.array([x + ds * np.cos(th), y + ds * np.sin(th), wrap_pi(th)])
    Rc = ds / dth
    x += Rc * (np.sin(th + dth) - np.sin(th))
    y += -Rc * (np.cos(th + dth) - np.cos(th))
    return np.array([x, y, wrap_pi(th + dth)])

def drive_lap(step_fn, lap):
    pose = np.array([0.0, 0.0, 0.0])
    for ds, dth in lap:
        pose = step_fn(pose, ds, dth)
    return pose

for label, fn in zip(("midpoint", "exact arc"), (odom_mid, odom_exact)):
    gap = float(np.linalg.norm(drive_lap(fn, LAP)[:2]))
    print("{:10} rounded corners, closing gap {:.3e} m ({:.2f} mm)".format(label, gap, gap * 1000))

spin = [float(np.linalg.norm(drive_lap(fn, SPIN_LAP)[:2])) for fn in (odom_mid, odom_exact)]
print("turn in place corners hide it, both close to {:.1e} and {:.1e} m".format(*spin))

