lessons.solution:
import numpy as np

R_WHEEL, L_BASE, DT = 0.033, 0.160, 0.05
L1, L2 = 0.20, 0.15
LIMITS = [(-np.pi, np.pi), (np.radians(10), np.radians(160))]
G, M1, M2, MP, TAU_MAX = 9.81, 0.35, 0.25, 0.2, 3.0

def wrap_pi(a):
    return (a + np.pi) % (2 * np.pi) - np.pi

def odom_exact(pose, ds, dth):
    x, y, th = pose
    if abs(dth) < 1e-9:
        return np.array([x + ds * np.cos(th), y + ds * np.sin(th), wrap_pi(th)])
    Rc = ds / dth
    return np.array([x + Rc * (np.sin(th + dth) - np.sin(th)),
                     y - Rc * (np.cos(th + dth) - np.cos(th)), wrap_pi(th + dth)])

def fk_2r(q):
    return np.array([L1 * np.cos(q[0]) + L2 * np.cos(q[0] + q[1]),
                     L1 * np.sin(q[0]) + L2 * np.sin(q[0] + q[1])])

def jac_2r(q):
    s1, c1 = np.sin(q[0]), np.cos(q[0])
    s12, c12 = np.sin(q[0] + q[1]), np.cos(q[0] + q[1])
    return np.array([[-L1 * s1 - L2 * s12, -L2 * s12], [L1 * c1 + L2 * c12, L2 * c12]])

def ik_2r_all(p):
    x, y = float(p[0]), float(p[1])
    c2 = (x * x + y * y - L1 * L1 - L2 * L2) / (2 * L1 * L2)
    q2a = float(np.arccos(np.clip(c2, -1.0, 1.0)))
    out = []
    for q2 in (q2a, -q2a):
        q1 = float(np.arctan2(y, x) - np.arctan2(L2 * np.sin(q2), L1 + L2 * np.cos(q2)))
        out.append(np.array([q1, q2]))
    return out

def gravity_torques(q):
    tau2 = G * np.cos(q[0] + q[1]) * (M2 * L2 / 2 + MP * L2)
    tau1 = tau2 + G * np.cos(q[0]) * (M1 * L1 / 2 + M2 * L1 + MP * L1)
    return np.array([tau1, tau2])

def pick_sequence(part_world, wheel_cmds, q_now=(0.5, 1.0)):
    pose = np.array([0.0, 0.0, 0.0])
    for wl, wr in wheel_cmds:
        v = R_WHEEL * (wr + wl) / 2.0
        om = R_WHEEL * (wr - wl) / L_BASE
        pose = odom_exact(pose, v * DT, om * DT)

    c, s = np.cos(pose[2]), np.sin(pose[2])
    Rw = np.array([[c, -s], [s, c]])
    p_base = Rw.T @ (np.asarray(part_world, float) - pose[:2])

    r = float(np.linalg.norm(p_base))
    if r > L1 + L2 or r < abs(L1 - L2):
        return {"status": "out_of_reach", "pose": pose, "p_base": p_base, "reach": r}

    sols = [q for q in ik_2r_all(p_base)
            if all(lo <= v <= hi for v, (lo, hi) in zip(q, LIMITS))]
    if not sols:
        return {"status": "no_solution_within_limits", "pose": pose, "p_base": p_base}

    q = min(sols, key=lambda x: float(np.linalg.norm(wrap_pi(x - np.asarray(q_now, float)))))
    J = jac_2r(q)
    w = float(np.sqrt(max(np.linalg.det(J @ J.T), 0.0)))
    tau = gravity_torques(q)
    if w < 1e-3:
        return {"status": "too_close_to_singularity", "q": q, "w": w}
    if np.any(np.abs(tau) > TAU_MAX):
        return {"status": "torque_exceeded", "q": q, "tau": tau}
    return {"status": "ok", "pose": pose, "p_base": p_base, "q": q, "w": w,
            "tau": tau, "tip_error": float(np.linalg.norm(fk_2r(q) - p_base))}

for part in (np.array([0.42, 0.05]), np.array([1.90, 0.60])):
    rep = pick_sequence(part, [(4.0, 4.0)] * 30)
    print("part", part, "->", rep["status"])
    if rep["status"] == "ok":
        print("  base pose:", np.round(rep["pose"], 5))
        print("  joints deg:", np.round(np.degrees(rep["q"]), 3), " manipulability:", round(rep["w"], 6))
        print("  torques N m:", np.round(rep["tau"], 4), " tip error:", round(rep["tip_error"], 12))
